CREATE TRIGGER catalog_work_products_insert AFTER INSERT ON products BEGIN INSERT INTO catalog_work (id, entity_type, entity_id, target_revision, processed_revision, created_at, updated_at) VALUES ('product:' || NEW.id, 'product', NEW.id, 1, 0, strftime('%Y-%m-%dT%H:%M:%fZ','now'), strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(entity_type, entity_id) DO UPDATE SET target_revision = target_revision + 1, updated_at = strftime('%Y-%m-%dT%H:%M:%fZ','now'); END;--> statement-breakpoint
